/**
 * Runtime support for vecDSL programs generated for Chroma with the chromadb SDK. Generated by vecDSL 7. Do not edit.
 */
import { readFileSync } from "node:fs";
import { AdminClient, ChromaClient } from "chromadb";
import type { Collection, Metadata, Where, WhereDocument } from "chromadb";

export const SDK_PACKAGE = "{{sdk.typescript.package}}";
export const SDK_VERSION = "{{sdk.typescript.version}}";

const PAGE = 256;
const BATCH = 100;
const DIGITS = 6;

export type Value = unknown;
export type Args = Record<string, unknown>;
export type Row = Record<string, unknown>;
type Layout = Record<string, any>;
type Filter = { where?: Where; where_document?: WhereDocument } | undefined;
type Entry = { id: string; embedding: number[]; metadata: Metadata; document: string | null };
type Page = { ids: string[]; embeddings: number[][]; metadatas: (Metadata | null)[]; documents: (string | null)[] };
type Include = "metadatas" | "documents" | "embeddings" | "distances";

export class UnsupportedFeature extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

/** The server endpoint, its tenant and default database, and one SDK client per database the program uses. */
export class Client {
  readonly host: string;
  readonly port: number;
  readonly ssl: boolean;
  private readonly clients = new Map<string, ChromaClient>();
  private adminClient?: AdminClient;

  constructor(uri: string, readonly tenant: string, readonly database: string) {
    const parsed = new URL(uri);
    this.ssl = parsed.protocol === "https:";
    this.host = parsed.hostname || "localhost";
    this.port = parsed.port ? Number(parsed.port) : this.ssl ? 443 : 8000;
  }

  db(database?: string | null): ChromaClient {
    const name = database ?? this.database;
    let client = this.clients.get(name);
    if (client === undefined) {
      client = new ChromaClient({ host: this.host, port: this.port, ssl: this.ssl, tenant: this.tenant, database: name });
      this.clients.set(name, client);
    }
    return client;
  }

  admin(): AdminClient {
    this.adminClient ??= new AdminClient({ host: this.host, port: this.port, ssl: this.ssl });
    return this.adminClient;
  }

  forget(database: string): void {
    this.clients.delete(database);
  }

  async close(): Promise<void> {
    this.clients.clear();
    this.adminClient = undefined;
  }
}

export async function connect(options: { uri: string; tenant?: string; database?: string }): Promise<Client> {
  return new Client(options.uri, options.tenant ?? "default_tenant", options.database ?? "default_database");
}

/** Chroma id of a primary key: the key's text; integral numbers print without a fraction. */
export function recordId(key: unknown): string {
  if (typeof key === "number") {
    if (!Number.isInteger(key)) {
      throw new TypeError(`cannot use ${key} as a Chroma primary key`);
    }
    return String(key);
  }
  if (typeof key === "string") {
    return key;
  }
  throw new TypeError(`cannot use ${JSON.stringify(key)} as a Chroma primary key`);
}

function value(item: unknown): unknown {
  if (typeof item === "number") {
    return Number(item.toFixed(DIGITS));
  }
  if (Array.isArray(item)) {
    return item.map(value);
  }
  if (item !== null && typeof item === "object") {
    return Object.fromEntries(Object.entries(item).map(([key, inner]) => [key, value(inner)]));
  }
  return item;
}

function chunks<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  for (let start = 0; start < items.length; start += size) {
    result.push(items.slice(start, start + size));
  }
  return result;
}

function compare(a: unknown, b: unknown): number {
  if (a === b) {
    return 0;
  }
  if (a === null || a === undefined) {
    return 1;
  }
  if (b === null || b === undefined) {
    return -1;
  }
  return (a as number | string) < (b as number | string) ? -1 : 1;
}

async function collectionOf(client: Client, collection: Layout): Promise<Collection> {
  return client.db(collection.database).getCollection({ name: collection.name });
}

function parts(filter: Filter): { where?: Where; whereDocument?: WhereDocument } {
  return { where: filter?.where ?? undefined, whereDocument: filter?.where_document ?? undefined };
}

// ---------------------------------------------------------------- databases and collections

export async function hasDatabase(client: Client, args: { name: string }): Promise<boolean> {
  const databases = await client.admin().listDatabases({ tenant: client.tenant });
  return databases.some((database) => database.name === args.name);
}

export async function createDatabase(client: Client, args: { name: string }): Promise<void> {
  await client.admin().createDatabase({ name: args.name, tenant: client.tenant });
}

export async function dropDatabase(client: Client, args: { name: string }): Promise<void> {
  await client.admin().deleteDatabase({ name: args.name, tenant: client.tenant });
  client.forget(args.name);
}

async function allCollections(client: Client, database?: string | null): Promise<Collection[]> {
  const found: Collection[] = [];
  for (;;) {
    const page = await client.db(database).listCollections({ limit: PAGE, offset: found.length });
    found.push(...page);
    if (page.length < PAGE) {
      return found;
    }
  }
}

export async function hasCollection(client: Client, args: { name: string; database?: string }): Promise<boolean> {
  return (await allCollections(client, args.database)).some((item) => item.name === args.name);
}

function collectionMetadata(metadata?: Record<string, unknown>): Metadata | undefined {
  if (metadata === undefined || Object.keys(metadata).length === 0) {
    return undefined;
  }
  return Object.fromEntries(
    Object.entries(metadata).map(([key, item]) => [key, key === "tags" ? JSON.stringify(item) : item]),
  ) as Metadata;
}

/** A collection whose embeddings the program supplies: no embedding function, the HNSW space and parameters given. */
export async function createCollection(
  client: Client,
  args: { name: string; metric: string; database?: string; hnsw?: Record<string, number>; metadata?: Record<string, unknown> },
): Promise<void> {
  await client.db(args.database).createCollection({
    name: args.name,
    configuration: { hnsw: { space: args.metric, ...(args.hnsw ?? {}) } } as never,
    metadata: collectionMetadata(args.metadata),
    embeddingFunction: null,
  });
}

export async function dropCollection(client: Client, args: { name: string; database?: string }): Promise<void> {
  await client.db(args.database).deleteCollection({ name: args.name });
}

/** The collection must exist; Chroma serves every collection and its metadata is schemaless. */
export async function requireCollection(client: Client, args: { name: string; database?: string }): Promise<void> {
  await client.db(args.database).getCollection({ name: args.name });
}

export async function renameCollection(client: Client, args: { name: string; new_name: string; database?: string }): Promise<void> {
  await (await client.db(args.database).getCollection({ name: args.name })).modify({ name: args.new_name });
}

/** Mutable HNSW parameters, and collection metadata merged into the stored metadata (modify replaces it). */
export async function alterCollection(
  client: Client,
  args: { name: string; database?: string; hnsw?: Record<string, number>; metadata?: Record<string, unknown> },
): Promise<void> {
  const handle = await client.db(args.database).getCollection({ name: args.name });
  if (args.hnsw !== undefined) {
    await handle.modify({ configuration: { hnsw: args.hnsw } });
  }
  if (args.metadata !== undefined) {
    await handle.modify({ metadata: { ...(handle.metadata ?? {}), ...collectionMetadata(args.metadata) } });
  }
}

/** Name, metadata and HNSW settings; the local server indexes every write before it answers, so progress is always ready. */
export async function describe(
  client: Client,
  args: { name: string; database?: string; stats?: boolean; index_progress?: boolean },
): Promise<Row> {
  const handle = await client.db(args.database).getCollection({ name: args.name });
  const hnsw = ((handle.configuration as Record<string, any>)?.hnsw ?? {}) as Record<string, unknown>;
  const metadata = Object.fromEntries(
    Object.entries(handle.metadata ?? {}).map(([key, item]) => [key, key === "tags" ? JSON.parse(String(item)) : item]),
  );
  const result: Row = {
    name: handle.name,
    database: args.database ?? client.database,
    metadata,
    hnsw: Object.fromEntries(
      Object.keys(hnsw)
        .filter((key) => hnsw[key] !== null && hnsw[key] !== undefined)
        .sort()
        .map((key) => [key, value(hnsw[key])]),
    ),
  };
  if (args.stats) {
    result.count = await handle.count();
  }
  if (args.index_progress) {
    result.index_progress = "ready";
  }
  return result;
}

export async function awaitIndex(client: Client, args: { name: string; database?: string }): Promise<string> {
  await requireCollection(client, args);
  return "ready";
}

/** Names of databases, collections, or the tenant or namespace values of a collection's slice key, sorted. */
export async function listObjects(
  client: Client,
  args: { kind: string; scope?: Layout; key?: string; prefix?: string; limit?: number },
): Promise<string[]> {
  let names: string[];
  if (args.kind === "databases") {
    names = (await client.admin().listDatabases({ tenant: client.tenant })).map((database) => database.name);
  } else if (args.kind === "collections") {
    names = (await allCollections(client, args.scope?.database)).map((item) => item.name);
  } else {
    const key = args.key as string;
    const rows = await rowsOf(client, args.scope as Layout, undefined, [key]);
    names = [...new Set(rows.filter((row) => row[key] !== null && row[key] !== undefined).map((row) => String(row[key])))];
  }
  names = names.filter((name) => args.prefix === undefined || name.startsWith(args.prefix)).sort();
  return args.limit === undefined ? names : names.slice(0, args.limit);
}

/** A new collection with the source's configuration and metadata, filled with a copy of every record. */
export async function cloneCollection(client: Client, args: { collection: Layout; target: string }): Promise<Row> {
  const source = await collectionOf(client, args.collection);
  const stored = ((source.configuration as Record<string, any>)?.hnsw ?? {}) as Record<string, unknown>;
  const hnsw: Record<string, unknown> = {};
  for (const key of ["ef_construction", "ef_search", "max_neighbors"]) {
    if (stored[key] !== null && stored[key] !== undefined) {
      hnsw[key] = stored[key];
    }
  }
  const copy = await client.db(args.collection.database).createCollection({
    name: args.target,
    configuration: { hnsw: { space: stored.space ?? "l2", ...hnsw } } as never,
    metadata: source.metadata && Object.keys(source.metadata).length > 0 ? source.metadata : undefined,
    embeddingFunction: null,
  });
  let copied = 0;
  for await (const page of pages(source, undefined, ["metadatas", "documents", "embeddings"])) {
    await copy.add({
      ids: page.ids,
      embeddings: page.embeddings,
      metadatas: page.metadatas as Metadata[],
      documents: page.documents.some((doc) => doc !== null) ? (page.documents as string[]) : undefined,
    });
    copied += page.ids.length;
  }
  return { copied };
}

// ---------------------------------------------------------------- records

function check(collection: Layout, record: Row): void {
  for (const [field, limit] of Object.entries((collection.limits ?? {}) as Record<string, Record<string, number>>)) {
    const item = record[field];
    if (item === null || item === undefined) {
      continue;
    }
    if (limit.max_items !== undefined && (item as unknown[]).length > limit.max_items) {
      throw new Error(`${field} has ${(item as unknown[]).length} items; at most ${limit.max_items} are allowed`);
    }
    if (limit.max_length !== undefined) {
      for (const text of Array.isArray(item) ? item : [item]) {
        if (typeof text === "string" && text.length > limit.max_length) {
          throw new Error(`${field} is longer than ${limit.max_length} characters`);
        }
      }
    }
  }
}

function isEmpty(item: unknown): boolean {
  return item === null || item === undefined || (Array.isArray(item) && item.length === 0);
}

/** Id, embedding, metadata and document of a record; null values and empty arrays are left out, as Chroma stores neither. */
function entryOf(collection: Layout, row: Row, slice?: Row): Entry {
  const record: Row = { ...(collection.defaults ?? {}), ...row, ...(slice ?? {}) };
  const key = record[collection.key];
  if (key === null || key === undefined) {
    throw new Error(`record without primary key ${collection.key}: ${JSON.stringify(row)}`);
  }
  check(collection, record);
  const vector = record[collection.vector] as number[] | null | undefined;
  if (vector === null || vector === undefined) {
    throw new Error(`record without vector ${collection.vector}: ${JSON.stringify(row)}`);
  }
  if (collection.dim !== undefined && vector.length !== collection.dim) {
    throw new Error(`${collection.vector} has ${vector.length} dimensions; ${collection.dim} are declared`);
  }
  const document = collection.document ? ((record[collection.document] as string | null | undefined) ?? null) : null;
  const metadata: Row = {};
  for (const [name, item] of Object.entries(record)) {
    if (name !== collection.vector && name !== collection.document && !isEmpty(item)) {
      metadata[name] = item;
    }
  }
  return { id: recordId(key), embedding: vector.map(Number), metadata: metadata as Metadata, document };
}

async function addEntries(handle: Collection, entries: Entry[], batchSize: number): Promise<void> {
  for (const chunk of chunks(entries, batchSize)) {
    const documents = chunk.map((entry) => entry.document);
    await handle.add({
      ids: chunk.map((entry) => entry.id),
      embeddings: chunk.map((entry) => entry.embedding),
      metadatas: chunk.map((entry) => entry.metadata),
      documents: documents.some((doc) => doc !== null) ? (documents as string[]) : undefined,
    });
  }
}

async function existing(handle: Collection, ids: string[]): Promise<string[]> {
  const found = new Set<string>();
  for (const chunk of chunks(ids, PAGE)) {
    (await handle.get({ ids: chunk, include: [] })).ids.forEach((id) => found.add(id));
  }
  return ids.filter((id) => found.has(id));
}

/** Chroma's add skips ids that exist, so conflicts are detected first: error raises, ignore skips them. */
export async function insertRows(
  client: Client,
  args: { collection: Layout; rows: Row[]; on_conflict?: string; batch_size?: number; slice?: Row },
): Promise<Row> {
  const handle = await collectionOf(client, args.collection);
  const entries = args.rows.map((row) => entryOf(args.collection, row, args.slice));
  const present = new Set(await existing(handle, entries.map((entry) => entry.id)));
  if (present.size > 0 && (args.on_conflict ?? "error") === "error") {
    throw new Error(`${present.size} records already exist in ${args.collection.name}`);
  }
  const fresh = entries.filter((entry) => !present.has(entry.id));
  await addEntries(handle, fresh, args.batch_size ?? BATCH);
  return { insert_count: fresh.length, skipped: entries.length - fresh.length };
}

/** Whole-record replacement: Chroma's upsert merges metadata, so existing records are deleted and added again. */
export async function upsertRows(
  client: Client,
  args: { collection: Layout; rows: Row[]; batch_size?: number; slice?: Row },
): Promise<Row> {
  const handle = await collectionOf(client, args.collection);
  const unique = new Map<string, Entry>();
  for (const row of args.rows) {
    const entry = entryOf(args.collection, row, args.slice);
    unique.delete(entry.id);
    unique.set(entry.id, entry);
  }
  const entries = [...unique.values()];
  for (const chunk of chunks(await existing(handle, entries.map((entry) => entry.id)), PAGE)) {
    await handle.delete({ ids: chunk });
  }
  await addEntries(handle, entries, args.batch_size ?? BATCH);
  return { upsert_count: entries.length };
}

/** Every record that matches a filter (and the ids, if given), page by page. */
async function* pages(handle: Collection, filter: Filter, include: Include[], ids?: string[]): AsyncGenerator<Page> {
  const { where, whereDocument } = parts(filter);
  for (let offset = 0; ; offset += PAGE) {
    const page = await handle.get({ ids, where, whereDocument, limit: PAGE, offset, include: include as never });
    if (page.ids.length === 0) {
      return;
    }
    yield { ids: page.ids, embeddings: page.embeddings, metadatas: page.metadatas, documents: page.documents };
    if (page.ids.length < PAGE) {
      return;
    }
  }
}

/**
 * Chroma's update request over HTTP: the SDK drops metadata keys set to null, which the server reads as deletions, so
 * updates bypass it (the same request the Python SDK and the Java runtime send).
 */
async function updateRecords(client: Client, handle: Collection, body: Row): Promise<void> {
  const path = `/api/v2/tenants/${encodeURIComponent(handle.tenant)}/databases/${encodeURIComponent(handle.database)}/collections/${handle.id}/update`;
  const response = await fetch(`${client.ssl ? "https" : "http"}://${client.host}:${client.port}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    throw new Error(`Chroma POST ${path} returned ${response.status}: ${await response.text()}`);
  }
}

function rowOf(collection: Layout, page: Page, index: number, output: string[], vectors: boolean): Row {
  const metadata = (page.metadatas?.[index] ?? {}) as Row;
  const row: Row = { [collection.key]: metadata[collection.key] ?? null };
  for (const name of output) {
    row[name] = name === collection.document ? (page.documents[index] ?? null) : value(metadata[name] ?? null);
  }
  if (vectors) {
    row[collection.vector] = value(page.embeddings[index].map(Number));
  }
  return row;
}

/** Matching records as rows (key first, then the output fields, then the vector if asked), in primary key order. */
async function rowsOf(client: Client, collection: Layout, filter: Filter, output: string[], ids?: string[], vectors = false): Promise<Row[]> {
  const handle = await collectionOf(client, collection);
  const include: Include[] = ["metadatas"];
  if (output.includes(collection.document)) {
    include.push("documents");
  }
  if (vectors) {
    include.push("embeddings");
  }
  const rows: Row[] = [];
  for await (const page of pages(handle, filter, include, ids)) {
    page.ids.forEach((_id, index) => rows.push(rowOf(collection, page, index, output, vectors)));
  }
  return rows.sort((a, b) => compare(a[collection.key], b[collection.key]));
}

async function idsOf(handle: Collection, filter: Filter, ids?: string[]): Promise<string[]> {
  const result: string[] = [];
  for await (const page of pages(handle, filter, [], ids)) {
    result.push(...page.ids);
  }
  return result;
}

/** Ids of the records a write selects: the given keys that exist and match the filter, or every match of the filter. */
async function targetsOf(handle: Collection, ids: unknown[] | undefined, filter: Filter): Promise<string[]> {
  if (ids !== undefined && ids.length > 0) {
    const wanted = [...new Set(ids.map(recordId))];
    if (filter !== undefined && Object.keys(filter).length > 0) {
      const matching = new Set(await idsOf(handle, filter, wanted));
      return wanted.filter((id) => matching.has(id));
    }
    return existing(handle, wanted);
  }
  if (filter !== undefined) {
    return idsOf(handle, filter);
  }
  throw new Error("the statement selects no records");
}

async function storedMetadata(handle: Collection, ids: string[]): Promise<Map<string, Row>> {
  const stored = new Map<string, Row>();
  for await (const page of pages(handle, undefined, ["metadatas"], ids)) {
    page.ids.forEach((id, index) => stored.set(id, (page.metadatas[index] ?? {}) as Row));
  }
  return stored;
}

/**
 * Chroma's update merges metadata and deletes the keys set to null; replace also clears the keys not given. A new document is
 * sent with the stored embedding, because the SDKs would otherwise embed the document.
 */
export async function updateRows(
  client: Client,
  args: {
    collection: Layout;
    ids?: unknown[];
    filter?: Filter;
    values?: Row;
    rows?: Row[];
    remove?: string[];
    mode?: string;
    append?: string[];
    remove_items?: string[];
  },
): Promise<Row> {
  const collection = args.collection;
  const handle = await collectionOf(client, collection);
  const key = collection.key as string;
  const replacements = new Map((args.rows ?? []).map((row) => [recordId(row[key]), row] as [string, Row]));
  let targets: string[];
  if (replacements.size > 0) {
    const chosen = new Set((args.ids ?? []).map(recordId));
    targets = (await targetsOf(handle, (args.rows ?? []).map((row) => row[key]), args.filter)).filter(
      (id) => chosen.size === 0 || chosen.has(id),
    );
  } else if ((args.ids ?? []).length > 0 || args.filter !== undefined) {
    targets = await targetsOf(handle, args.ids, args.filter);
  } else {
    throw new Error("update requires ids, a filter or records");
  }
  if (targets.length === 0) {
    return { update_count: 0 };
  }
  const document: string | undefined = collection.document;
  const redocument =
    document !== undefined && (document in (args.values ?? {}) || (args.rows ?? []).some((row) => document in row));
  const stored = new Map<string, Row>();
  const embeddings = new Map<string, number[]>();
  for await (const page of pages(handle, undefined, redocument ? ["metadatas", "embeddings"] : ["metadatas"], targets)) {
    page.ids.forEach((id, index) => {
      stored.set(id, (page.metadatas[index] ?? {}) as Row);
      if (redocument) {
        embeddings.set(id, page.embeddings[index].map(Number));
      }
    });
  }
  const append = args.append ?? [];
  const removeItems = args.remove_items ?? [];
  for (const id of targets) {
    const record: Row = { ...(replacements.get(id) ?? {}), ...(args.values ?? {}) };
    if (key in record && recordId(record[key]) !== id) {
      throw new Error(`update cannot change the primary key ${key}`);
    }
    const current = stored.get(id) ?? {};
    const metadata: Row = {};
    for (const [name, given] of Object.entries(record)) {
      if (name === collection.vector || name === collection.document || name === key) {
        continue;
      }
      let item: unknown = given;
      if (append.includes(name)) {
        item = [...((current[name] as unknown[]) ?? []), ...((given as unknown[]) ?? [])];
      } else if (removeItems.includes(name)) {
        const dropped = (given as unknown[]) ?? [];
        item = ((current[name] as unknown[]) ?? []).filter((element) => !dropped.includes(element));
      }
      metadata[name] = Array.isArray(item) && item.length === 0 ? null : item;
    }
    for (const name of args.remove ?? []) {
      metadata[name] = null;
    }
    if (args.mode === "replace") {
      for (const name of Object.keys(current)) {
        if (name !== key && !(name in metadata)) {
          metadata[name] = null;
        }
      }
    }
    check(collection, metadata);
    const given = record[collection.vector] as number[] | null | undefined;
    const hasDocument = document !== undefined && document in record;
    const vector = given !== null && given !== undefined ? given.map(Number) : hasDocument ? embeddings.get(id) : undefined;
    if (Object.keys(metadata).length > 0 || vector !== undefined || hasDocument) {
      const body: Row = { ids: [id] };
      if (Object.keys(metadata).length > 0) {
        body.metadatas = [metadata];
      }
      if (vector !== undefined) {
        body.embeddings = [vector];
      }
      if (hasDocument) {
        body.documents = [record[document]];
      }
      await updateRecords(client, handle, body);
    }
  }
  return { update_count: targets.length };
}

/** Deletes by id after resolving the targets, so the count is exact; limit takes the first targets in key order. */
export async function deleteRows(
  client: Client,
  args: { collection: Layout; ids?: unknown[]; filter?: Filter; delete_all?: boolean; limit?: number },
): Promise<Row> {
  const handle = await collectionOf(client, args.collection);
  const hasIds = (args.ids ?? []).length > 0;
  let targets = args.delete_all && !hasIds ? await idsOf(handle, args.filter) : await targetsOf(handle, args.ids, args.filter ?? (hasIds ? undefined : {}));
  if (args.limit !== undefined) {
    const stored = await storedMetadata(handle, targets);
    targets = [...targets]
      .sort((a, b) => compare((stored.get(a) ?? {})[args.collection.key], (stored.get(b) ?? {})[args.collection.key]))
      .slice(0, args.limit);
  }
  for (const chunk of chunks(targets, PAGE)) {
    await handle.delete({ ids: chunk });
  }
  return { delete_count: targets.length };
}

async function updateEach(client: Client, handle: Collection, changes: [string, Row][]): Promise<void> {
  for (const chunk of chunks(changes, PAGE)) {
    await updateRecords(client, handle, { ids: chunk.map(([id]) => id), metadatas: chunk.map(([, metadata]) => metadata) });
  }
}

/** Writes a new field's default into every record that lacks it. */
export async function fillField(client: Client, args: { collection: Layout; field: string; value: unknown }): Promise<Row> {
  const handle = await collectionOf(client, args.collection);
  const changes: [string, Row][] = [];
  for await (const page of pages(handle, undefined, ["metadatas"])) {
    page.ids.forEach((id, index) => {
      const stored = (page.metadatas[index] ?? {}) as Row;
      if (stored[args.field] === null || stored[args.field] === undefined) {
        changes.push([id, { [args.field]: args.value }]);
      }
    });
  }
  await updateEach(client, handle, changes);
  return { update_count: changes.length };
}

/** Removes a metadata key from every record (Chroma deletes a key set to null). */
export async function dropField(client: Client, args: { collection: Layout; field: string }): Promise<Row> {
  const handle = await collectionOf(client, args.collection);
  const changes: [string, Row][] = [];
  for await (const page of pages(handle, undefined, ["metadatas"])) {
    page.ids.forEach((id, index) => {
      if (args.field in ((page.metadatas[index] ?? {}) as Row)) {
        changes.push([id, { [args.field]: null }]);
      }
    });
  }
  await updateEach(client, handle, changes);
  return { update_count: changes.length };
}

/** Moves a metadata key to a new name in every record that has it. */
export async function renameField(client: Client, args: { collection: Layout; field: string; new_name: string }): Promise<Row> {
  const handle = await collectionOf(client, args.collection);
  const changes: [string, Row][] = [];
  for await (const page of pages(handle, undefined, ["metadatas"])) {
    page.ids.forEach((id, index) => {
      const stored = (page.metadatas[index] ?? {}) as Row;
      if (args.field in stored) {
        changes.push([id, { [args.new_name]: stored[args.field], [args.field]: null }]);
      }
    });
  }
  for (const [id, metadata] of changes) {
    await updateRecords(client, handle, { ids: [id], metadatas: [metadata] });
  }
  return { update_count: changes.length };
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Row[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const text = readFileSync(path, "utf-8");
  if (text.trimStart().startsWith("[")) {
    return JSON.parse(text) as Row[];
  }
  return text
    .split(/\r?\n/)
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line) as Row);
}

export async function importFile(
  client: Client,
  args: { collection: Layout; location: string; on_conflict?: string; batch_size?: number; slice?: Row },
): Promise<Row> {
  const rows = await readRecords(client, { location: args.location });
  if (args.on_conflict === "update" || args.on_conflict === "replace") {
    return upsertRows(client, { collection: args.collection, rows, batch_size: args.batch_size, slice: args.slice });
  }
  return insertRows(client, { collection: args.collection, rows, on_conflict: args.on_conflict ?? "error", batch_size: args.batch_size, slice: args.slice });
}

// ---------------------------------------------------------------- reads

/** Records by primary key, in the order of the keys given. */
export async function getRows(
  client: Client,
  args: { collection: Layout; ids: unknown[]; output: string[]; filter?: Filter; vectors?: boolean },
): Promise<Row[]> {
  const wanted = [...new Set(args.ids.map(recordId))];
  const rows = await rowsOf(client, args.collection, args.filter, args.output, wanted, args.vectors ?? false);
  const found = new Map(rows.map((row) => [recordId(row[args.collection.key]), row] as [string, Row]));
  return wanted.filter((id) => found.has(id)).map((id) => found.get(id) as Row);
}

export async function count(client: Client, args: { collection: Layout; filter?: Filter }): Promise<number> {
  const handle = await collectionOf(client, args.collection);
  if (args.filter === undefined || Object.keys(args.filter).length === 0) {
    return handle.count();
  }
  return (await idsOf(handle, args.filter)).length;
}

/** Records in primary key order, or in the order of the sort fields; Chroma returns them in insertion order. */
export async function scroll(
  client: Client,
  args: {
    collection: Layout;
    output: string[];
    filter?: Filter;
    limit?: number;
    offset?: number;
    order?: { key: string; direction?: string }[];
    vectors?: boolean;
  },
): Promise<Row[]> {
  const collection = args.collection;
  const order = args.order ?? [];
  const fields = [...new Set([...args.output, ...order.map((item) => item.key).filter((name) => name !== collection.key)])];
  let rows = await rowsOf(client, collection, args.filter, fields, undefined, args.vectors ?? false);
  for (const item of [...order].reverse()) {
    const sign = item.direction === "desc" ? -1 : 1;
    rows = [...rows].sort((a, b) => sign * compare(a[item.key], b[item.key]));
  }
  rows = rows.slice(args.offset ?? 0);
  if (args.limit !== undefined) {
    rows = rows.slice(0, args.limit);
  }
  const names = [collection.key, ...args.output, ...(args.vectors ? [collection.vector] : [])];
  return rows.map((row) => Object.fromEntries(names.map((name) => [name, row[name] ?? null])));
}

/** A random sample (or the first records in key order) of the matching records. */
export async function sampleRows(
  client: Client,
  args: { collection: Layout; size: number; output: string[]; first?: boolean; filter?: Filter },
): Promise<Row[]> {
  const rows = await rowsOf(client, args.collection, args.filter, args.output);
  if (args.first) {
    return rows.slice(0, args.size);
  }
  const pool = [...rows];
  const picked: Row[] = [];
  while (picked.length < args.size && pool.length > 0) {
    picked.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  }
  return picked.sort((a, b) => compare(a[args.collection.key], b[args.collection.key]));
}

/** Canonical similarity of a Chroma distance: l2 is squared Euclidean, cosine and ip are 1 minus the similarity. */
export function similarity(metric: string, distance: number): number {
  return metric === "l2" ? -Math.sqrt(Math.max(distance, 0)) : 1 - distance;
}

export async function lookupVector(client: Client, args: { collection: Layout; id: unknown }): Promise<number[]> {
  const found = await (await collectionOf(client, args.collection)).get({ ids: [recordId(args.id)], include: ["embeddings"] as never });
  if (found.ids.length === 0) {
    throw new Error(`record ${JSON.stringify(args.id)} not found in ${args.collection.name}`);
  }
  return found.embeddings[0].map(Number);
}

function within(score: number, min?: number, max?: number): boolean {
  return (min === undefined || score >= min) && (max === undefined || score <= max);
}

async function nearest(
  handle: Collection,
  collection: Layout,
  vector: number[],
  size: number,
  filter: Filter,
  output: string[],
  vectors: boolean,
  native: boolean,
): Promise<[Row, number][]> {
  const include: Include[] = ["metadatas", "distances"];
  if (output.includes(collection.document)) {
    include.push("documents");
  }
  if (vectors) {
    include.push("embeddings");
  }
  const { where, whereDocument } = parts(filter);
  const result = await handle.query({ queryEmbeddings: [vector.map(Number)], nResults: size, where, whereDocument, include: include as never });
  const page: Page = {
    ids: result.ids[0] ?? [],
    embeddings: (result.embeddings?.[0] ?? []) as number[][],
    metadatas: result.metadatas?.[0] ?? [],
    documents: result.documents?.[0] ?? [],
  };
  const distances = result.distances?.[0] ?? [];
  return page.ids.map((_id, index) => {
    const distance = Number(distances[index]);
    return [rowOf(collection, page, index, output, vectors), native ? distance : similarity(collection.metric, distance)];
  });
}

function hitsOf(
  collection: Layout,
  hits: [Row, number][],
  offset: number | undefined,
  limit: number,
  min: number | undefined,
  max: number | undefined,
  native: boolean,
): Row[] {
  const start = offset ?? 0;
  return [...hits]
    .sort((a, b) => (native ? a[1] - b[1] : b[1] - a[1]))
    .slice(start, start + limit)
    .filter(([, score]) => within(score, min, max))
    .map(([row, score]) => {
      const { [collection.key]: id, ...rest } = row;
      return { id, score: value(score), ...rest };
    });
}

/** Nearest neighbours by the collection's HNSW space; offset pages the ranking, bounds apply to the canonical similarity. */
export async function vectorSearch(
  client: Client,
  args: {
    collection: Layout;
    vector: number[];
    limit: number;
    output: string[];
    filter?: Filter;
    offset?: number;
    score_min?: number;
    score_max?: number;
    native?: boolean;
    vectors?: boolean;
  },
): Promise<Row[]> {
  const native = args.native ?? false;
  const handle = await collectionOf(client, args.collection);
  const size = args.limit + (args.offset ?? 0);
  const hits = await nearest(handle, args.collection, args.vector, size, args.filter, args.output, args.vectors ?? false, native);
  return hitsOf(args.collection, hits, args.offset, args.limit, args.score_min, args.score_max, native);
}

/** The average-vector strategy, avg(positive) + (avg(positive) - avg(negative)); example records are not returned. */
export async function recommend(
  client: Client,
  args: {
    collection: Layout;
    positives: unknown[];
    limit: number;
    output: string[];
    negatives?: unknown[];
    lookup?: Layout;
    filter?: Filter;
    offset?: number;
    score_min?: number;
    score_max?: number;
    native?: boolean;
    vectors?: boolean;
  },
): Promise<Row[]> {
  const collection = args.collection;
  const native = args.native ?? false;
  const source = args.lookup ?? collection;
  const example = async (item: unknown): Promise<number[]> =>
    Array.isArray(item) ? item.map(Number) : lookupVector(client, { collection: source, id: item });
  const mean = (vectors: number[][]): number[] => vectors[0].map((_x, i) => vectors.reduce((sum, v) => sum + v[i], 0) / vectors.length);
  const good = await Promise.all(args.positives.map(example));
  const bad = await Promise.all((args.negatives ?? []).map(example));
  const positive = mean(good);
  const query = bad.length > 0 ? positive.map((p, i) => 2 * p - mean(bad)[i]) : positive;
  const excluded = new Set(
    [...args.positives, ...(args.negatives ?? [])]
      .filter((item) => !Array.isArray(item) && source.name === collection.name)
      .map(recordId),
  );
  const handle = await collectionOf(client, collection);
  const size = args.limit + (args.offset ?? 0) + excluded.size;
  const hits = (await nearest(handle, collection, query, size, args.filter, args.output, args.vectors ?? false, native)).filter(
    ([row]) => !excluded.has(recordId(row[collection.key])),
  );
  return hitsOf(collection, hits, args.offset, args.limit, args.score_min, args.score_max, native);
}

/**
 * A random sample of the matching records, each paired with its nearest neighbours within the sample (as Qdrant's distance
 * matrix), with primary keys and canonical similarities, sorted by key.
 */
export async function distanceMatrix(
  client: Client,
  args: { collection: Layout; sample?: number; limit?: number; filter?: Filter },
): Promise<Row[]> {
  const collection = args.collection;
  const handle = await collectionOf(client, collection);
  const records: [unknown, string, number[]][] = [];
  for await (const page of pages(handle, args.filter, ["metadatas", "embeddings"])) {
    page.ids.forEach((id, index) => records.push([(page.metadatas[index] as Row)[collection.key], id, page.embeddings[index].map(Number)]));
  }
  const picked: [unknown, string, number[]][] = [];
  while (picked.length < (args.sample ?? 10) && records.length > 0) {
    picked.push(records.splice(Math.floor(Math.random() * records.length), 1)[0]);
  }
  const ids = picked.map(([, id]) => id);
  const limit = args.limit ?? 3;
  const pairs: Row[] = [];
  for (const [key, id, vector] of picked) {
    const result = await handle.query({
      queryEmbeddings: [vector],
      nResults: Math.min(limit + 1, ids.length),
      ids,
      include: ["metadatas", "distances"] as never,
    });
    const neighbours = result.ids[0]
      .map((other, index) => [other, (result.metadatas[0][index] as Row)[collection.key], Number(result.distances[0][index])] as const)
      .filter(([other]) => other !== id)
      .slice(0, limit);
    for (const [, otherKey, distance] of neighbours) {
      pairs.push({ a: key, b: otherKey, score: value(similarity(collection.metric, distance)) });
    }
  }
  return pairs.sort((x, y) => compare(x.a, y.a) || compare(x.b, y.b));
}
